const chatId = $('Dados').first().json.chatId;
const msg = $('Juntar').first().json.message || '';
const mem = $('Ler memoria').first().json || {};
const seg = mem.seg || 0;
const lastMsg = mem.lastMsg || '';
const ts = mem.ts || 0;
const longMem = mem.longMem || '';
const now = Date.now();
const gapMin = ts ? Math.round((now - ts) / 60000) : 99999;
return [{ json: { message: msg, chatId: chatId, prevMsg: lastMsg, seg: seg, gapMin: gapMin, longMem: longMem } }];

const prev = $('Ctx: ler').first().json;
const chatId = prev.chatId;
const msg = prev.message;
const decision = String($input.first().json.text || '').toUpperCase();
const isNew = decision.indexOf('NOVO') !== -1 || (prev.gapMin || 0) > 360;
let seg = prev.seg || 0;
if (isNew) seg = seg + 1;
return [{ json: { message: msg, seg: seg, chatId: chatId, ctxDecision: isNew ? 'NOVO' : 'CONTINUA', longMem: prev.longMem || '' } }];

