const chatId = $('Ctx: aplicar').first().json.chatId;
const summary = String($input.first().json.text || '').trim();
return [{ json: { longMem: summary, chatId: chatId } }];

const data = $getWorkflowStaticData('global');
if (!data.seen) data.seen = [];
const id = $input.first().json.playload_id || '';
if (id && data.seen.indexOf(id) !== -1) return [];
if (id) { data.seen.push(id); if (data.seen.length > 300) data.seen = data.seen.slice(-300); }
// Boot cutoff: rejeita mensagens com mais de 5 minutos de idade.
const msgTs = $input.first().json.msgTimestamp || 0;
if (msgTs && (Date.now() - msgTs) > 5 * 60 * 1000) return [];
return $input.all();

const out = String($('AI Agent').first().json.output || '').trim();
const NL = String.fromCharCode(10);
let parts;
if (out.indexOf('|||') !== -1) { parts = out.split('|||'); }
else { parts = out.split(NL + NL); }
parts = parts.map(function(s){ return s.trim(); }).filter(function(s){ return s.length; });
if (parts.length === 0) parts = [out];
if (parts.length > 5) { parts = parts.slice(0,4).concat([parts.slice(4).join(NL + NL)]); }
return parts.map(function(p){ return { json: { text: p } }; });

const latest = $input.first().json.latestTok;
const mine = $('Dados').first().json.playload_id;
if (String(latest) !== String(mine)) { return []; }
return $input.all();

const buf = $('Fila buffer').first().json.bufList;
const list = Array.isArray(buf) ? buf : (buf ? [buf] : []);
let message = list.join(' ').trim();
if (!message) message = String($('Dados').first().json.message || '');
const dados = $('Dados').first().json;
const ctxParts = [];
if (dados.isSticker) ctxParts.push('[contexto: figurinha]');
if (dados.isForwarded) ctxParts.push('[contexto: mensagem encaminhada]');
if (dados.isReply && dados.quotedText) ctxParts.push('[contexto: respondendo a "' + dados.quotedText + '"]');
else if (dados.isReply) ctxParts.push('[contexto: mensagem de resposta]');
const ctxPrefix = ctxParts.length ? ctxParts.join(' ') + '\n' : '';
message = ctxPrefix + message;
return [{ json: { message: message } }];

// Gate do liga/desliga (M2): para o fluxo se a automacao estiver desligada.
const cfg = $('Get runtime config').first().json;
if (cfg && cfg.enabled === false) return [];
return $('Ctx: aplicar').all();
